function spGcd(a, b){ a = Math.abs(Math.round(a)); b = Math.abs(Math.round(b)); while(b){ var t = a % b; a = b; b = t; } return a || 1; }
function spPeriods(R, r){ return Math.round(r / spGcd(R, r)); }
function spPoint(kind, R, r, d, t){
  if(kind === 'epi'){
    var k = (R + r) / r;
    return { x: (R + r) * Math.cos(t) - d * Math.cos(k * t), y: (R + r) * Math.sin(t) - d * Math.sin(k * t) };
  }
  var k2 = (R - r) / r;
  return { x: (R - r) * Math.cos(t) + d * Math.cos(k2 * t), y: (R - r) * Math.sin(t) - d * Math.sin(k2 * t) };
}
function spCurve(kind, R, r, d, steps){
  var per = spPeriods(R, r), total = Math.PI * 2 * per;
  var n = steps || Math.max(720, per * 240), pts = [];
  for(var i=0;i<=n;i++) pts.push(spPoint(kind, R, r, d, total * i / n));
  return pts;
}
function spSvg(kind, R, r, d, size, color){
  var pts = spCurve(kind, R, r, d);
  var maxR = kind === 'epi' ? R + r + d : Math.abs(R - r) + d;
  var sc = (size/2 - 10) / Math.max(maxR, 1);
  var path = '';
  for(var i=0;i<pts.length;i++){
    var x = (size/2 + pts[i].x * sc).toFixed(2), y = (size/2 + pts[i].y * sc).toFixed(2);
    path += (i === 0 ? 'M' : 'L') + x + ' ' + y;
  }
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + size + ' ' + size + '" width="' + size + '" height="' + size + '">'
    + '<rect width="' + size + '" height="' + size + '" fill="#0A0A0B"/>'
    + '<path d="' + path + '" fill="none" stroke="' + (color || '#22D3EE') + '" stroke-width="1.2" stroke-opacity="0.9"/></svg>';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { spGcd:spGcd, spPeriods:spPeriods, spPoint:spPoint, spCurve:spCurve, spSvg:spSvg };
}
if (typeof window !== 'undefined') {
  window.SpiroForgePure = { spGcd:spGcd, spPeriods:spPeriods, spPoint:spPoint, spCurve:spCurve, spSvg:spSvg };
